const now = new Date().toISOString();
const policy = { policy_version: 'g8n.france-travail.pagination.v1', range_size: 50, max_pages_per_run: 20, max_calls_per_run: 30, retryable_http_statuses: [408, 429, 500, 502, 503, 504], non_retryable_http_statuses: [400, 401, 403, 404, 409, 422], max_attempts_per_page: 3, base_delay_seconds: 2, max_delay_seconds: 120, respect_retry_after: true, jitter_max_seconds: 3 };
return [{ json: { run_id: `ft_pages_${now.replace(/[-:.]/g, '').slice(0, 15)}Z`, schema_version: 'g8n.workflow-envelope.v1', source: { workflow_id: 'WF-10', workflow_name: 'WF-10 — France Travail pagination checkpoint skeleton', node_name: 'Prepare — Pagination policy', origin: 'manual_local' }, timestamps: { started_at: now, finished_at: null }, payload: { config_version: 'g8n.france-travail.search.v1', query_hash: 'manual-query-hash-placeholder', current_range: '0-49', policy, page_result: null, persistence_result: { persisted: false, reason: 'G8N-023 persistence not wired in skeleton' } }, checkpoint: { last_persisted_range: null, next_range: '0-49', advance_allowed: false }, counters: { calls: 0, pages_seen: 0, pages_persisted: 0, offers_seen: 0, offers_persisted: 0, retries: 0, errors: 0 }, errors: [] } }];

const input = $input.first().json;
const status = Number(input.payload.page_result?.http_status || 200);
const retryAfter = input.payload.page_result?.retry_after || null;
const policy = input.payload.policy;
const isRetryable = policy.retryable_http_statuses.includes(status);
const isNonRetryable = policy.non_retryable_http_statuses.includes(status) || (status >= 400 && status < 500 && status !== 429);
const errors = [...input.errors];
let pageState = 'ready_to_persist';
let delaySeconds = 0;
if (status === 401) pageState = 'credential_action_required';
else if (status === 403) pageState = 'authorization_action_required';
else if (status === 429) {
  pageState = 'rate_limited';
  delaySeconds = retryAfter ? Number(retryAfter) : policy.base_delay_seconds;
} else if (isRetryable) {
  pageState = 'retryable_error';
  delaySeconds = Math.min(policy.max_delay_seconds, policy.base_delay_seconds);
} else if (isNonRetryable) pageState = 'non_retryable_error';
if (pageState !== 'ready_to_persist') errors.push({ code: `G8N_FT_${String(status)}`, category: pageState, recoverable: isRetryable, masked: true, retry_after_seconds: delaySeconds });
const pageOffers = input.payload.page_result?.offer_ids || [];
return [{ json: { ...input, payload: { ...input.payload, page_state: pageState, retry_after_seconds: delaySeconds }, counters: { ...input.counters, calls: input.counters.calls + 1, pages_seen: input.counters.pages_seen + (status === 200 ? 1 : 0), offers_seen: input.counters.offers_seen + pageOffers.length, retries: input.counters.retries + (pageState === 'retryable_error' || pageState === 'rate_limited' ? 1 : 0), errors: errors.length }, errors } }];

const input = $input.first().json;
const [start, end] = String(input.payload.current_range).split('-').map(Number);
const rangeSize = input.payload.policy.range_size;
const persistenceSucceeded = input.payload.persistence_result.persisted === true;
const nextStart = end + 1;
const nextEnd = nextStart + rangeSize - 1;
const nextRange = `${nextStart}-${nextEnd}`;
const repeatedRange = input.checkpoint.last_persisted_range === input.payload.current_range;
const maxCallsReached = input.counters.calls >= input.payload.policy.max_calls_per_run;
const canAdvance = input.payload.page_state === 'ready_to_persist' && persistenceSucceeded && !repeatedRange;
let status = 'partial';
if (canAdvance && !maxCallsReached) status = 'ready_for_next_page';
if (maxCallsReached) status = 'partial_call_budget_reached';
if (repeatedRange) status = 'partial_pagination_loop_guard';
return [{ json: { ...input, status, checkpoint: { last_persisted_range: canAdvance ? input.payload.current_range : input.checkpoint.last_persisted_range, next_range: canAdvance ? nextRange : input.checkpoint.next_range, advance_allowed: canAdvance }, counters: { ...input.counters, pages_persisted: input.counters.pages_persisted + (canAdvance ? 1 : 0), offers_persisted: input.counters.offers_persisted + (canAdvance ? (input.payload.page_result?.offer_ids || []).length : 0) } } }];
